import shutil
import openpyxl

def to_int(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return int(value)
    if isinstance(value, str):
        s = value.strip()
        if s.lstrip("-").isdigit():
            return int(s)
    return None

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Sheet1" if "Sheet1" in wb.sheetnames else wb.active.title
ws = wb[sheet_name]
vws = vals[sheet_name] if sheet_name in vals.sheetnames else vals.active

yes_by_question = {}
for row in range(1, vws.max_row + 1):
    qnum = to_int(vws.cell(row=row, column=1).value)
    if qnum is None:
        continue
    yes_val = vws.cell(row=row, column=3).value
    yes_by_question[qnum] = yes_val is not None and str(yes_val).strip().lower() == "x"

totals = []
for col in range(6, 10):  # F, G, H, I
    total = 0
    for row in range(4, 24):  # include row 4 through row 23
        qnum = to_int(vws.cell(row=row, column=col).value)
        if qnum is not None and yes_by_question.get(qnum, False):
            total += 1
    totals.append(total)

for col, total in zip(range(6, 10), totals):
    ws.cell(row=25, column=col).value = total

print("sheet:", sheet_name)
print("yes questions:", [q for q, v in sorted(yes_by_question.items()) if v])
print("totals F25:I25:", totals)

wb.save(OUT)
